//#region src/core/utils/authorization-header.ts
/**
* Classifies the raw `Authorization` header.
*
* {@link extractCredentials} only reads `Authorization: Bearer <token>`, so a
* wrong scheme, wrong casing, or a bare token silently produces no credential —
* which reads to the caller as "you sent nothing", the single most confusing way
* for auth to fail. This is the one place that distinction is worked out, so
* `verifyAuth` and the `withRequiredClaims` gate report an identical request
* identically.
*
* @param raw - The header value, or `null` when absent.
*
* @internal
*/
function diagnoseAuthorizationHeader(raw) {
	if (!raw) return { kind: "absent" };
	const [scheme = "", ...rest] = raw.split(" ");
	if (scheme === "Bearer") {
		const token = rest.join(" ").trim();
		if (!token) return {
			kind: "unreadable",
			reason: "the Authorization header used the `Bearer` scheme but carried an empty token",
			hint: "Put the JWT after `Bearer `, separated by a single space."
		};
		return token.startsWith("sb_") ? { kind: "api-key" } : { kind: "bearer" };
	}
	if (scheme.toLowerCase() === "bearer") return {
		kind: "unreadable",
		reason: `the Authorization header used the scheme "${scheme}" rather than \`Bearer\``,
		hint: "The scheme is case-sensitive: it must be exactly `Bearer`, capitalised, followed by a single space and the JWT."
	};
	if (rest.length > 0) return {
		kind: "unreadable",
		reason: `the Authorization header used the "${scheme}" scheme, not \`Bearer\``,
		hint: "Only `Authorization: Bearer <jwt>` is read as a user credential."
	};
	return {
		kind: "unreadable",
		reason: "the Authorization header carried a bare value with no scheme",
		hint: "It must be `Authorization: Bearer <jwt>` — the scheme is not optional."
	};
}
/**
* Diagnosis for an `sb_*` API key found in the `Authorization` header. Shared so
* `verifyCredentials` and the claims gate word it the same way.
*
* @internal
*/
const ApiKeyInAuthorizationHeader = {
	reason: "the Authorization header carried an sb_* API key, not a user JWT",
	hint: "API keys belong in the `apikey` header. The Supabase SDK sends the key in both the `apikey` and `Authorization` headers, which is why this is easy to miss."
};
/**
* Diagnosis for Supabase API keys arriving at an endpoint that reads none — a
* `user`-only gate. supabase-js sends the publishable key in both the `apikey`
* and `Authorization` headers, so an unauthenticated client lands here with a
* key in each slot; reporting "your key matched nothing" would send the caller
* hunting for a key mismatch that does not exist. Shared so `verifyCredentials`
* and the claims gate word an identical request identically.
*
* @internal
*/
function apiKeyOnUserOnlyEndpoint(slots) {
	return {
		reason: slots.inApiKeyHeader ? "an apikey header, which no accepted auth mode reads" : "an sb_* API key in the Authorization header, which no accepted auth mode reads",
		hint: "This endpoint authenticates a user, not a project — an API key can never satisfy it, whichever header it arrives in." + (slots.inAuthorization ? " supabase-js sends the publishable key in both the `apikey` and `Authorization` headers, so an unauthenticated client lands here even though a bearer token appears to have been sent; a signed-in session's access token replaces it." : "")
	};
}
//#endregion
//#region src/core/utils/classify-credentials.ts
/**
* Classifies an `apikey` value by its public prefix so a format mismatch can be
* reported in an error without echoing the key itself.
*
* Sending a secret key to a publishable-only endpoint (or a legacy
* `anon` / `service_role` JWT to either) is a far more common mistake than a
* genuinely wrong key, and the prefix is enough to tell them apart.
*
* @internal
*/
function classifyApiKey(apikey) {
	if (!apikey) return "absent";
	if (apikey.startsWith("sb_publishable_")) return "publishable";
	if (apikey.startsWith("sb_secret_")) return "secret";
	if (apikey.startsWith("eyJ")) return "legacy-jwt";
	return "unrecognized";
}
//#endregion
export { diagnoseAuthorizationHeader as i, ApiKeyInAuthorizationHeader as n, apiKeyOnUserOnlyEndpoint as r, classifyApiKey as t };
